from pathlib import Path
import sys

PROJECT_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(PROJECT_ROOT))
from backend.app.sql.sql_agent import SQLAgent
from backend.app.database_config import load_database_config


def main():
    print("=" * 70)
    print("TESTING COMPLETE SQL PIPELINE")
    print("=" * 70)

    db_config = load_database_config(require_explicit=True)
    agent = SQLAgent(
        **db_config,
        max_rows=100,
    )

    questions = [
        "What was the revenue generated by campaign CMP-021?",
        "What was the spend of campaign CMP-021?",
        "How many conversions did campaign CMP-021 generate?",
        "What was the performance of campaign CMP-021?",
    ]

    for index, question in enumerate(questions, start=1):

        print("\n" + "=" * 70)
        print(f"TEST {index}")
        print("=" * 70)

        print("\nQuestion:")
        print(question)

        # ---------------------------------------------------------
        # Run complete pipeline
        # ---------------------------------------------------------

        response = agent.answer(question)

        # ---------------------------------------------------------
        # Query Plan
        # ---------------------------------------------------------

        print("\nQuery Plan:")
        print("-" * 70)

        print(response["query_plan"])

        # ---------------------------------------------------------
        # Generated SQL
        # ---------------------------------------------------------

        print("\nGenerated SQL:")
        print("-" * 70)

        print(response["sql"])

        # ---------------------------------------------------------
        # Validation
        # ---------------------------------------------------------

        print("\nValidation:")
        print("-" * 70)

        print(response["validation"])

        # ---------------------------------------------------------
        # Database Result
        # ---------------------------------------------------------

        print("\nDatabase Result:")
        print("-" * 70)

        print("Columns:")
        print(response["result"]["columns"])

        print("\nRows:")

        for row in response["result"]["rows"]:
            print(row)

        print("\nRow count:")
        print(response["result"]["row_count"])

        # ---------------------------------------------------------
        # Assertions
        # ---------------------------------------------------------

        assert response["query_plan"]["entity_id"] == "CMP-021"

        assert response["query_plan"]["table"] == (
            "marketing_campaigns"
        )

        assert response["validation"]["valid"] is True

        assert response["result"]["row_count"] == 1

        print("\nPASS")

    # -------------------------------------------------------------
    # Unsupported question
    # -------------------------------------------------------------

    print("\n" + "=" * 70)
    print("TEST 5 — UNSUPPORTED QUESTION")
    print("=" * 70)

    question = "What is the average order value of customers?"

    print("\nQuestion:")
    print(question)

    try:
        agent.answer(question)

        raise AssertionError(
            "Unsupported question should have raised ValueError."
        )

    except ValueError as error:

        print("\nExpected error:")
        print(error)

        print("\nPASS")

    # -------------------------------------------------------------
    # Empty question
    # -------------------------------------------------------------

    print("\n" + "=" * 70)
    print("TEST 6 — EMPTY QUESTION")
    print("=" * 70)

    try:
        agent.answer("")

        raise AssertionError(
            "Empty question should have raised ValueError."
        )

    except ValueError as error:

        print("\nExpected error:")
        print(error)

        print("\nPASS")

    print("\n" + "=" * 70)
    print("COMPLETE SQL PIPELINE TEST PASSED")
    print("=" * 70)


if __name__ == "__main__":
    main()